body.push(p("\u56e2\u961f\u9762\u5411\u5728\u6821\u5b66\u751f\u5f00\u5c55\u4e86\u9700\u6c42\u8c03\u7814\uff0c\u7ed3\u8bba\u663e\u793a\u6821\u56ed\u4fe1\u606f\u54a8\u8be2\u5b58\u5728\u4e09\u7c7b\u6838\u5fc3\u75db\u70b9\uff1a\u4e00\u662f\u4fe1\u606f\u5206\u6563\uff0c\u9009\u8bfe\u3001\u5956\u52a9\u3001\u5bbf\u820d\u7b49\u89c4\u7ae0\u5206\u5c5e\u4e0d\u540c\u90e8\u95e8\u7f51\u7ad9\uff0c\u5b66\u751f\u96be\u4ee5\u5b9a\u4f4d\uff1b\u4e8c\u662f\u65f6\u6548\u53d7\u9650\uff0c\u4eba\u5de5\u54a8\u8be2\u4f9d\u8d56\u5de5\u4f5c\u65f6\u95f4\uff0c\u665a\u95f4\u4e0e\u5047\u671f\u65e0\u6cd5\u53ca\u65f6\u54cd\u5e94\uff1b\u4e09\u662f\u56de\u7b54\u53e3\u5f84\u4e0d\u4e00\uff0c\u540c\u4e00\u95ee\u9898\u4e0d\u540c\u6e20\u9053\u5f97\u5230\u7684\u7b54\u6848\u53ef\u80fd\u4e0d\u4e00\u81f4\uff0c\u7f3a\u4e4f\u6743\u5a01\u53e3\u5f84\u4e0e\u6765\u6e90\u6807\u6ce8\u3002"));
body.push(h2("2.2  \u6280\u672f\u65b9\u6848\u8c03\u7814"));
body.push(p("\u56f4\u7ed5\u300c\u5982\u4f55\u8ba9\u5927\u6a21\u578b\u51c6\u786e\u56de\u7b54\u6821\u56ed\u4e8b\u52a1\u95ee\u9898\u300d\uff0c\u56e2\u961f\u5bf9\u6bd4\u4e86\u4e09\u7c7b\u6280\u672f\u8def\u7ebf\uff1a\u5fae\u4fe1\u516c\u4f17\u53f7\u5173\u952e\u8bcd\u81ea\u52a8\u56de\u590d\uff08\u62d3\u5c55\u6027\u5dee\u3001\u65e0\u8bed\u4e49\u7406\u89e3\uff09\u3001\u7eaf\u5927\u6a21\u578b\u76f4\u63a5\u751f\u6210\uff08\u5b58\u5728\u5e7b\u89c9\u98ce\u9669\u3001\u77e5\u8bc6\u65f6\u6548\u6027\u5dee\u3001\u79c1\u6709\u6570\u636e\u65e0\u6cd5\u5165\u6a21\uff09\u4e0e RAG \u68c0\u7d22\u589e\u5f3a\u751f\u6210\u3002RAG \u5c06\u9886\u57df\u77e5\u8bc6\u4ee5\u5916\u6302\u65b9\u5f0f\u6ce8\u5165\u751f\u6210\u8fc7\u7a0b\uff0c\u517c\u987e\u51c6\u786e\u6027\u4e0e\u53ef\u7ef4\u62a4\u6027\uff0c\u662f\u5f53\u524d\u884c\u4e1a\u4e3b\u6d41\u65b9\u6848\u3002"));
body.push(p("\u5728 RAG \u5185\u90e8\u8bbe\u8ba1\u4e0a\uff0c\u8c03\u7814\u5f62\u6210\u4e86\u4e09\u9879\u5173\u952e\u7ed3\u8bba\uff1a\u7b2c\u4e00\uff0c\u5355\u4e00\u5411\u91cf\u68c0\u7d22\u5bf9\u4e13\u6709\u540d\u8bcd\u3001\u7f16\u53f7\u7c7b\u67e5\u8be2\uff08\u5982\u300c\u56fe\u4e66\u9986\u300d\u3001\u300c\u6821\u56ed\u5361\u300d\uff09\u7684\u547d\u4e2d\u4e0d\u7a33\u5b9a\uff0c\u751f\u4ea7\u5b9e\u8df5\u666e\u904d\u91c7\u7528 BM25 \u4e0e\u7a20\u5bc6\u5411\u91cf\u5e76\u884c\u7684\u6df7\u5408\u68c0\u7d22\uff0c\u518d\u7ecf RRF \u878d\u5408\u4e0e\u91cd\u6392\u5e8f\u7cbe\u9009\uff1b\u7b2c\u4e8c\uff0c\u6570\u636e\u6e05\u6d17\u4e0e\u5206\u5757\u7b56\u7565\u5bf9\u68c0\u7d22\u8d28\u91cf\u7684\u6295\u5165\u4ea7\u51fa\u6bd4\u6700\u9ad8\uff0c\u5e94\u4f18\u5148\u5efa\u8bbe\u77e5\u8bc6\u8fd0\u8425\u89c4\u8303\uff08\u542b\u540c\u4e49\u8bcd\u6807\u7b7e\uff09\uff1b\u7b2c\u4e09\uff0c\u6d41\u5f0f\u8f93\u51fa\uff08SSE/WebSocket\uff09\u5bf9\u957f\u56de\u7b54\u7684\u4f53\u9a8c\u81f3\u5173\u91cd\u8981\uff0cSSE \u5728\u5355\u5411\u63a8\u9001\u573a\u666f\u4e0b\u66f4\u8f7b\u91cf\u4e14\u5bf9\u7f51\u5173\u53cb\u597d\u3002\u4e0a\u8ff0\u7ed3\u8bba\u5747\u5728\u672c\u7cfb\u7edf\u8bbe\u8ba1\u4e2d\u5f97\u5230\u843d\u5b9e\u3002"));
body.push(h2("2.3  \u540c\u7c7b\u7cfb\u7edf\u8c03\u7814"));
body.push(p("\u56fd\u5185\u9ad8\u6821\u5df2\u6709\u4e00\u6279\u843d\u5730\u6848\u4f8b\uff1a\u5317\u4eac\u5927\u5b66\u6863\u6848\u9986\u57fa\u4e8e RAG \u6784\u5efa\u5168\u57df\u77e5\u8bc6\u670d\u52a1\u7cfb\u7edf\uff0c\u5165\u9009\u56fd\u5bb6\u6863\u6848\u5c40\u4fe1\u606f\u5316\u521b\u65b0\u6848\u4f8b\uff1b\u65b0\u4e61\u5b66\u9662\u300c\u5c0f\u65b0\u65e0\u5fe7\u300d\u5e73\u53f0\u5c06\u89c4\u7ae0\u5236\u5ea6\u4e0e\u529e\u4e8b\u6d41\u7a0b\u6784\u5efa\u6821\u672c\u77e5\u8bc6\u5e93\u5e76\u5b9e\u65f6\u66f4\u65b0\uff1b\u767e\u5ea6 AI \u9762\u5411\u6559\u80b2\u573a\u666f\u63d0\u4f9b\u4e86\u57fa\u4e8e\u5b98\u7f51\u6570\u636e\u7684\u6821\u56ed\u95ee\u7b54\u52a9\u624b\u65b9\u6848\u3002\u8fd9\u4e9b\u6848\u4f8b\u9a8c\u8bc1\u4e86\u65b9\u5411\u53ef\u884c\u6027\uff0c\u4f46\u666e\u904d\u4f9d\u8d56\u5546\u4e1a\u5e73\u53f0\uff0c\u5b66\u751f\u56e2\u961f\u96be\u4ee5\u5b66\u4e60\u5176\u5185\u90e8\u67b6\u6784\uff1b\u672c\u9879\u76ee\u7684\u5dee\u5f02\u5316\u5b9a\u4f4d\u662f\u300c\u53ef\u5b8c\u6574\u8dd1\u901a\u3001\u53ef\u62c6\u89e3\u5b66\u4e60\u3001\u53ef\u6f14\u8fdb\u5230\u751f\u4ea7\u5f62\u6001\u300d\u7684\u6559\u5b66\u53cb\u597d\u578b\u5b9e\u73b0\u3002"));

/* ---- 3 需求分析 ---- */
body.push(h1("3  \u9700\u6c42\u5206\u6790"));
body.push(h2("3.1  \u7528\u6237\u89d2\u8272\u4e0e\u6838\u5fc3\u573a\u666f"));
body.push(p("\u7cfb\u7edf\u6d89\u53ca\u4e09\u7c7b\u89d2\u8272\uff1a\u5b66\u751f\uff08\u63d0\u95ee\u4e0e\u6d4f\u89c8\u56de\u7b54\uff09\u3001\u77e5\u8bc6\u7ba1\u7406\u5458\uff08\u7ef4\u62a4\u6821\u56ed\u77e5\u8bc6\u5e93\u3001\u5904\u7406\u65b0\u589e\u4e0e\u66f4\u65b0\uff09\u3001\u7cfb\u7edf\u7ba1\u7406\u5458\uff08\u76d1\u63a7\u8fd0\u884c\u6307\u6807\u4e0e\u5bb9\u91cf\u89c4\u5212\uff09\u3002\u6838\u5fc3\u573a\u666f\u5305\u62ec\uff1a\u65b0\u751f\u5165\u5b66\u54a8\u8be2\u3001\u65e5\u5e38\u4e8b\u52a1\u529e\u7406\u3001\u5956\u52a9\u7533\u62a5\u5b63\u9ad8\u5cf0\u54a8\u8be2\u3001\u665a\u95f4\u7d27\u6025\u4e8b\u52a1\u67e5\u8be2\u7b49\u3002"));
body.push(h2("3.2  \u529f\u80fd\u9700\u6c42"));
body.push(tblTitle("\u8868 3-1  \u529f\u80fd\u9700\u6c42\u6e05\u5355\uff08FR\uff09"));
body.push(tbl(["\u7f16\u53f7", "\u9700\u6c42", "\u4f18\u5148\u7ea7", "\u9a8c\u6536\u6807\u51c6"], [
  ["FR-1", "\u81ea\u7136\u8bed\u8a00\u63d0\u95ee\uff0c\u83b7\u5f97\u5e26\u5f15\u7528\u6eaf\u6e90\u7684\u56de\u7b54", "\u9ad8", "\u56de\u7b54\u9644\u5e26\u6765\u6e90\u3001\u5206\u7c7b\u3001\u68c0\u7d22\u8bc1\u636e"],
  ["FR-2", "\u6d41\u5f0f\u8f93\u51fa\uff0c\u56de\u7b54\u9010\u5b57\u5448\u73b0", "\u9ad8", "\u9996\u5b57\u5ef6\u8fdf < 1s"],
  ["FR-3", "\u4f1a\u8bdd\u7ba1\u7406\uff1a\u5386\u53f2\u4f1a\u8bdd\u5217\u8868\u4e0e\u518d\u52a0\u8f7d", "\u4e2d", "\u5237\u65b0\u540e\u53ef\u6062\u590d\u5386\u53f2\u5bf9\u8bdd"],
  ["FR-4", "\u77e5\u8bc6\u5e93\u7ba1\u7406\uff1a\u5206\u7c7b\u6d4f\u89c8\u3001\u68c0\u7d22\u3001\u65b0\u589e\u6761\u76ee", "\u9ad8", "\u65b0\u589e\u6761\u76ee\u540e\u65e0\u9700\u91cd\u542f\u5373\u53ef\u88ab\u68c0\u7d22"],
  ["FR-5", "\u8fd0\u884c\u770b\u677f\uff1a\u63d0\u95ee\u91cf\u3001\u547d\u4e2d\u7387\u3001\u65f6\u5ef6\u3001\u70ed\u70b9\u5206\u7c7b", "\u4e2d", "\u6307\u6807\u5b9e\u65f6\u5237\u65b0"],
  ["FR-6", "\u65e0\u76f8\u5173\u77e5\u8bc6\u65f6\u7ed9\u51fa\u8bda\u5b9e\u517c\u5bb9\u56de\u7b54", "\u9ad8", "\u4e0d\u7f16\u9020\u7b54\u6848\uff0c\u5f15\u5bfc\u6362\u95ee\u6cd5"],
], [10, 42, 10, 38]));
body.push(h2("3.3  \u8d28\u91cf\u5c5e\u6027\u9700\u6c42\uff08\u573a\u666f\u516d\u5143\u7ec4\uff09"));
body.push(p("\u91c7\u7528\u8d28\u91cf\u5c5e\u6027\u573a\u666f\u516d\u5143\u7ec4\uff08\u523a\u6fc0\u6e90\u3001\u523a\u6fc0\u5de5\u4ef6\u3001\u73af\u5883\u3001\u6d4b\u91cf\u3001\u54cd\u5e94\u3001\u9a8c\u6536\u6807\u51c6\uff09\u63cf\u8ff0\u5173\u952e\u975e\u529f\u80fd\u9700\u6c42\uff0c\u6458\u5f55\u5982\u8868 3-2\u3002"));
body.push(tblTitle("\u8868 3-2  \u8d28\u91cf\u5c5e\u6027\u573a\u666f"));
body.push(tbl(["\u5c5e\u6027", "\u573a\u666f\u63cf\u8ff0\uff08\u523a\u6fc0\u6e90\u2192\u54cd\u5e94\uff09", "\u91cf\u5316\u76ee\u6807"], [
  ["\u6027\u80fd", "\u5956\u52a9\u7533\u62a5\u5b63\u5f00\u5b66\u9996\u5468\uff0c\u5e76\u53d1\u63d0\u95ee\u91cf\u5cf0\u503c\u4e3a\u5e73\u65f6 5 \u500d\uff0c\u7cfb\u7edf\u5e94\u4fdd\u6301\u54cd\u5e94\u4e0d\u962a\u5854", "\u68c0\u7d22 P95 < 50ms\uff1b\u9996\u5b57\u5ef6\u8fdf < 1s\uff1b\u5355\u673a\u541e\u5410 \u2265 50 QPS"],
  ["\u53ef\u7528\u6027", "\u4e91\u7aef LLM \u670d\u52a1\u8d85\u65f6\u6216\u6545\u969c\u65f6\uff0c\u7cfb\u7edf\u5e94\u81ea\u52a8\u964d\u7ea7\u7ee7\u7eed\u670d\u52a1", "\u964d\u7ea7\u5207\u6362\u65e0\u9700\u4eba\u5de5\uff1b\u6574\u4f53\u53ef\u7528\u6027 \u2265 99.5%"],
  ["\u53ef\u4fee\u6539\u6027", "\u77e5\u8bc6\u5e93\u65b0\u589e/\u4fee\u6b63\u6761\u76ee\u540e\uff0c\u65b0\u77e5\u8bc6\u5e94\u7acb\u5373\u751f\u6548", "\u7d22\u5f15\u70ed\u66f4\u65b0 < 5s\uff0c\u65e0\u9700\u91cd\u542f\u670d\u52a1"],
  ["\u53ef\u6269\u5c55\u6027", "\u7528\u6237\u91cf\u589e\u957f\u65f6\u901a\u8fc7\u52a0\u526f\u672c\u6c34\u5e73\u6269\u5bb9\uff0c\u800c\u975e\u91cd\u6784", "\u5e94\u7528\u65e0\u72b6\u6001\u5316\uff0c\u652f\u6301 N \u526f\u672c\u8d1f\u8f7d\u5747\u8861"],
  ["\u5b89\u5168\u6027", "\u5355\u4e2a\u7528\u6237\u5f02\u5e38\u9ad8\u9891\u8bf7\u6c42\u4e0d\u5e94\u62d6\u57ae\u670d\u52a1", "\u4ee4\u724c\u6876\u9650\u6d41 5 QPS/\u7528\u6237\uff0c\u8d85\u9650 429"],
  ["\u53ef\u6d4b\u8bd5\u6027", "\u68c0\u7d22\u8d28\u91cf\u53d8\u5316\u5e94\u53ef\u88ab\u91cf\u5316\u8bc4\u4f30", "\u5185\u7f6e Hit@K/MRR \u8bc4\u6d4b\u811a\u672c\uff0c\u53ef\u5728 CI \u4e2d\u8fd0\u884c"],
], [12, 55, 33]));
body.push(h2("3.4  \u7ea6\u675f\u6761\u4ef6"));
body.push(p("\u9879\u76ee\u9762\u4e34\u56db\u9879\u5173\u952e\u7ea6\u675f\uff1a\uff081\uff09\u8bfe\u7a0b\u5468\u671f\u4ec5 8 \u5468\uff0c\u56e2\u961f 3\u20135 \u4eba\uff0c\u4e0d\u5141\u8bb8\u91cd\u578b\u5fae\u670d\u52a1\u5168\u5bb6\u6876\u5f0f\u8bd5\u9519\uff1b\uff082\uff09\u5b66\u751f\u73af\u5883\u9884\u7b97\u6709\u9650\uff0c\u4e91\u8d44\u6e90\u4e0e\u5927\u578b\u5546\u4e1a\u6a21\u578b\u4e0d\u53ef\u4f5c\u4e3a\u6f14\u793a\u7684\u786c\u4f9d\u8d56\uff1b\uff083\uff09\u6821\u56ed\u4fe1\u606f\u5177\u6709\u6743\u5a01\u53e3\u5f84\uff0c\u56de\u7b54\u5fc5\u987b\u53ef\u6eaf\u6e90\u3001\u4e0d\u5f97\u7f16\u9020\uff1b\uff084\uff09\u9700\u5728\u666e\u901a\u7b14\u8bb0\u672c\u4e0a\u4e00\u952e\u542f\u52a8\u6f14\u793a\u3002\u8fd9\u4e9b\u7ea6\u675f\u76f4\u63a5\u5851\u9020\u4e86\u7b2c 4 \u7ae0\u7684\u67b6\u6784\u9009\u578b\u4e0e\u7b2c 8 \u7ae0\u7684\u51b3\u7b56\u3002"));

