body.push(h2("4.1  \u67b6\u6784\u98ce\u683c\u4e0e\u6a21\u5f0f\u9009\u578b"));
body.push(p("\u7cfb\u7edf\u91c7\u7528\u300c\u6a21\u5757\u5316\u5355\u4f53 + \u6e05\u6670\u5206\u5c42 + \u9884\u7559\u670d\u52a1\u5316\u8fb9\u754c\u300d\u7684\u67b6\u6784\u98ce\u683c\uff1a\u6f14\u793a\u5f62\u6001\u4e3a\u5355\u4f53\u5e94\u7528\u4ee5\u964d\u4f4e\u90e8\u7f72\u590d\u6742\u5ea6\uff0c\u4f46\u4ee3\u7801\u6309\u9886\u57df\u4e25\u683c\u5212\u5206\u6a21\u5757\uff08api / services / repository / core\uff09\uff0c\u6a21\u5757\u95f4\u4ec5\u901a\u8fc7\u63a5\u53e3\u4f9d\u8d56\uff0c\u4e3a\u540e\u7eed\u62c6\u5206\u5fae\u670d\u52a1\u4fdd\u7559\u8fb9\u754c\u3002\u5173\u952e\u6a21\u5f0f\u5305\u62ec\uff1a\u5206\u5c42\u6a21\u5f0f\uff08\u63a5\u5165\u2192\u7f51\u5173\u2192\u5e94\u7528\u2192\u5f15\u64ce\u2192\u6570\u636e\uff09\u3001\u7ba1\u9053-\u8fc7\u6ee4\u5668\u6a21\u5f0f\uff08RAG \u6444\u53d6\u2192\u68c0\u7d22\u2192\u878d\u5408\u2192\u91cd\u6392\u2192\u751f\u6210\u6d41\u6c34\u7ebf\uff09\u3001\u63d0\u4f9b\u8005\u6a21\u5f0f\uff08Embedding / Reranker / Generator \u4e09\u4e2a\u63d2\u4ef6\u63a5\u53e3\uff09\u4e0e\u4ee3\u7406\u6a21\u5f0f\uff08LLM Provider \u8fdc\u7a0b\u8c03\u7528\uff09\u3002"));
