body.push(h2("5.1  \u77e5\u8bc6\u6444\u53d6\u4e0e\u5206\u5757\u7b56\u7565"));
body.push(p("\u77e5\u8bc6\u4ee5 QA \u5bf9\u4e3a\u5355\u4f4d\u5165\u5e93\uff0c\u6bcf\u6761\u62c6\u5206\u4e3a\u4e24\u7c7b\u5206\u5757\uff1a\u95ee\u9898\u901a\u9053\uff08\u95ee\u6cd5 + \u7b54\u6848\u62fc\u63a5\uff0c\u8d1f\u8d23\u95ee\u6cd5\u5339\u914d\uff09\u4e0e\u7b54\u6848\u901a\u9053\uff08\u6309\u53e5\u53f7\u6ed1\u7a97\u4e8c\u6b21\u5207\u5757\uff0c\u6bcf\u5757\u4e0d\u8d85\u8fc7 3 \u53e5\uff0c\u8d1f\u8d23\u5185\u5bb9\u8986\u76d6\uff09\u3002\u6bcf\u4e2a\u5206\u5757\u643a\u5e26 doc_id \u4fbf\u4e8e\u805a\u5408\u56de\u539f\u6587\u6863\u5b9e\u73b0\u5f15\u7528\u6eaf\u6e90\uff0c\u5e76\u9644\u5e26\u5206\u7c7b\u3001\u6765\u6e90\u3001\u540c\u4e49\u8bcd\u6807\u7b7e\u3002\u5f53\u524d\u79cd\u5b50\u8bed\u6599 59 \u7bc7\u6587\u6863\u5171 136 \u4e2a\u5206\u5757\u3002"));
body.push(h2("5.2  \u6df7\u5408\u68c0\u7d22\uff1aBM25 \u2225 \u5411\u91cf\u53cc\u901a\u9053"));
body.push(p("\u7a00\u758f\u901a\u9053\u4e3a\u81ea\u5b9e\u73b0 BM25\uff08k1=1.5\u3001b=0.75\uff0cjieba \u641c\u7d22\u5f15\u64ce\u5206\u8bcd\uff09\uff0c\u64c5\u957f\u4e13\u6709\u540d\u8bcd\u4e0e\u7f16\u53f7\u67e5\u8be2\u3002\u7a20\u5bc6\u901a\u9053\u7531 EmbeddingProvider \u63a5\u53e3\u627f\u8f7d\uff1a\u672c\u8f6e\u5df2\u5b9e\u73b0\u4e91\u7aef\u8bed\u4e49\u5411\u91cf Provider\uff08\u667a\u8c31 embedding-3\uff0c\u542b\u5411\u91cf\u7f13\u5b58\u4e0e\u6545\u969c\u56de\u9000\uff09\uff0c\u4f46\u672a\u914d\u7f6e API Key \u65f6\u6309\u914d\u7f6e\u81ea\u52a8\u56de\u9000 TF-IDF \u52a0\u6743\u8bcd\u888b\u5411\u91cf\uff08\u6f14\u793a\u8fd0\u884c\u6001\u5982\u5b9e\u4e3a TF-IDF\uff0c\u975e\u8bed\u4e49\u5d4c\u5165\uff1b\u524d\u7aef\u4e0e\u7edf\u8ba1\u63a5\u53e3\u5747\u540c\u6b65\u663e\u793a\u5f53\u524d\u5411\u91cf Provider \u4e0e\u7d22\u5f15\u7248\u672c\uff09\u3002\u4e24\u8def\u7ed3\u679c\u7ecf RRF \u878d\u5408\uff08\u516c\u5f0f\uff1ascore = \u03a3 1/(k+\u6392\u540d)\uff0ck=60\uff09\uff0c\u5bf9\u6392\u540d\u800c\u975e\u5206\u6570\u878d\u5408\uff0c\u514d\u9664\u5206\u6570\u5f52\u4e00\u5316\u96be\u9898\u3002\u878d\u5408\u8f93\u51fa\u7ecf\u91cd\u6392\u4e0e\u6587\u6863\u7ea7\u53bb\u91cd\u540e\u4ea4\u4ed8\u751f\u6210\u3002"));
body.push(h2("5.3  \u91cd\u6392\u5e8f\u4e0e\u751f\u6210"));
body.push(p("\u878d\u5408\u540e\u7684\u5019\u9009\u96c6\uff08\u4e0d\u622a\u65ad\uff0c\u907f\u514d\u540c\u6587\u6863\u53cc\u901a\u9053 chunk \u6324\u5360\u540d\u989d\uff09\u8fdb\u5165\u91cd\u6392\u5668\uff1a\u6f14\u793a\u5b9e\u73b0\u4e3a\u7279\u5f81\u5316\u8f7b\u91cf\u91cd\u6392\uff08\u5b9e\u8d28\u8bcd\u8986\u76d6 30% + \u4e8c\u5143\u8bcd\u91cd\u53e0 20% + \u53e5\u5b50\u7ea7\u91cd\u53e0 35% + \u540c\u4e49\u8bcd\u6807\u7b7e\u547d\u4e2d 15%\uff0c\u5b9e\u8d28\u8bcd\u96f6\u4ea4\u96c6\u786c\u5f52\u96f6\uff09\u3002\u57fa\u4e8e 62 \u6761\u8bc4\u6d4b\u7684\u5b9e\u8bc1\u7ed3\u8bba\uff1a\u8f7b\u91cf\u8bcd\u9762\u91cd\u6392\u65e0\u6cd5\u7a33\u5b9a\u8d85\u8d8a\u53cc\u901a\u9053\u6392\u5e8f\uff0c\u56e0\u6b64\u6700\u7ec8\u6392\u5e8f\u91c7\u7528 RRF \u5148\u9a8c\u4e3a\u4e3b\uff080.7\uff09\u3001\u91cd\u6392\u7cbe\u8c03\u4e3a\u8f85\uff080.3\uff09\u7684\u7ec4\u5408\u7b56\u7565\uff0c\u5e76\u4ee5\u91cd\u6392\u539f\u59cb\u5206\u7684\u5168\u6709\u6216\u65e0\u95e8\u69db\u4f5c\u4e3a\u65e0\u77e5\u8bc6\u5151\u5e95\u5224\u636e\uff1b\u6392\u5e8f\u589e\u76ca\u7684\u8fdb\u4e00\u6b65\u63d0\u5347\u9700\u63a5\u5165 Cross-Encoder\uff08\u63a5\u53e3\u9884\u7559\uff09\u3002\u751f\u6210\u670d\u52a1\u901a\u8fc7 GeneratorProvider \u63d0\u4f9b\u4e24\u79cd\u5b9e\u73b0\uff1a\u672c\u5730\u62bd\u53d6\u5f0f\u751f\u6210\u5668\u57fa\u4e8e\u68c0\u7d22\u7247\u6bb5\u62bd\u53e5\u5408\u6210\u5e76\u6d41\u5f0f\u8f93\u51fa\uff0c\u4f5c\u4e3a\u96f6\u4f9d\u8d56\u6f14\u793a\u4e0e\u964d\u7ea7\u5151\u5e95\uff1b\u4e91\u7aef GLM\uff08openai \u517c\u5bb9\u534f\u8bae\uff09\u4e3a\u751f\u4ea7\u63a8\u8350\uff0c\u63d0\u793a\u8bcd\u7ea6\u675f\u5176\u4ec5\u4f9d\u636e\u53c2\u8003\u8d44\u6599\u4f5c\u7b54\u3002"));
